package ayre;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

import ayre.enums.AyreStatus;
import ayre.enums.ReplyType;

// Generated by GPT-5.6 Luna
/** Tests the high-level application response flow without mutating task data. */
public class AyreTest {
    @Test
    public void getResponse_bye_returnsTerminationResponse() {
        Ayre ayre = new Ayre();
        AyreResponse response = ayre.getResponse("bye");

        assertEquals("~ Terminating connection. See you again, Raven.\n", response.message());
        assertEquals(ReplyType.NORMAL, response.type());
        assertEquals(AyreStatus.TERMINATE, response.status());
    }

    @Test
    public void getResponse_unknownCommand_returnsErrorResponse() {
        Ayre ayre = new Ayre();
        AyreResponse response = ayre.getResponse("unknown");

        assertEquals("~ ...Raven, this command was not found in the Coral Collective. Was it a mistake?",
                response.message());
        assertEquals(ReplyType.ERROR, response.type());
        assertEquals(AyreStatus.CONTINUE, response.status());
    }
}
